int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);
	cout << fixed << setprecision(10);
	int N, M;
	longlong mod;
	cin >> N >> M >> mod;
	vector<longlong> factorial(N+1, 1), inv_factorial(N+1, 1);
	for(int i = 1; i <= N; i++) {
		factorial[i] = factorial[i-1] * i % mod;
		inv_factorial[i] = inv_factorial[i-1] * power(i, mod-2, mod) % mod;
	}
	vector<longlong> count(M+1, 0);
	vector<longlong> sum(M+1, 0);
	count[0] = 1;
	for(int m = 1; m <= M; m++) {
		for(int k = 0; k < m; k++) {
			longlong left_count = count[k] * inv_factorial[k] % mod;
			longlong right_count = count[m-1-k] * inv_factorial[m-1-k] % mod;
			longlong left_sum = sum[k] * inv_factorial[k] % mod;
			longlong right_sum = sum[m-1-k] * inv_factorial[m-1-k] % mod;
			count[m] += left_count * right_count % mod * (m+1);
			sum[m] += (left_sum * right_sum + left_count * right_sum + left_sum * right_count) % mod * (m+1);
			sum[m] += left_count * right_count % mod * (k*(k+1)+(m-k)*(m-k-1))/2 % mod;
		}
		count[m] = count[m] % mod * factorial[m-1] % mod;
		sum[m] = sum[m] % mod * factorial[m-1] % mod;
	}
	vector<vector<longlong>> count_ans(N+1, vector<longlong>(M+1, 0));
	vector<vector<longlong>> sum_ans(N+1, vector<longlong>(M+1, 0));
	count_ans[0][0] = 1;
	for(int i = 1; i <= N; i++) {
		for(int j = 0; j <= min(i, M); j++) {
			count_ans[i][j] = count_ans[i-1][j];
			sum_ans[i][j] = sum_ans[i-1][j];
			if(j == i) {
				count_ans[i][j] += count[i] * inv_factorial[i] % mod;
				sum_ans[i][j] += sum[i] * inv_factorial[i] % mod;
			}
			for(int k = 1; k <= min(j, i-1); k++) {
				longlong c = count[k] * inv_factorial[k] % mod;
				longlong s = sum[k] * inv_factorial[k] % mod;
				count_ans[i][j] += count_ans[i-1-k][j-k] * c % mod;
				sum_ans[i][j] += (sum_ans[i-1-k][j-k] * c + count_ans[i-1-k][j-k] * s) % mod;
			}
			count_ans[i][j] %= mod;
			sum_ans[i][j] %= mod;
		}
	}
	longlong answer = sum_ans[N][M] * factorial[M] % mod;
	cout << answer << "\n";
